import React from 'react';
import { StatusBar } from 'expo-status-bar';
import { StyleSheet, View, Platform } from 'react-native';
import { WebView } from 'react-native-webview';

const GAME_HTML = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no,viewport-fit=cover\"/>\n<title>Chisanbop</title>\n<script src=\"https://unpkg.com/react@18/umd/react.production.min.js\"></script>\n<script src=\"https://unpkg.com/react-dom@18/umd/react-dom.production.min.js\"></script>\n<script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n<style>\n*{box-sizing:border-box;margin:0;padding:0;}\nhtml,body{height:100%;background:#ff6d00;overflow-x:hidden;}\n#root{min-height:100vh;}\n</style>\n</head>\n<body>\n<div id=\"root\"></div>\n<script type=\"text/babel\" data-presets=\"react\">\nconst {useState,useEffect,useRef,useCallback}=React;\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   FINGER DATA\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nconst FR=[\n  {id:\"r_pinky\",label:\"Kelingking\",value:1,isThumb:false},\n  {id:\"r_ring\",label:\"Manis\",value:1,isThumb:false},\n  {id:\"r_middle\",label:\"Tengah\",value:1,isThumb:false},\n  {id:\"r_index\",label:\"Telunjuk\",value:1,isThumb:false},\n  {id:\"r_thumb\",label:\"Ibu Jari\",value:5,isThumb:true},\n];\nconst FL=[\n  {id:\"l_thumb\",label:\"Ibu Jari\",value:50,isThumb:true},\n  {id:\"l_index\",label:\"Telunjuk\",value:10,isThumb:false},\n  {id:\"l_middle\",label:\"Tengah\",value:10,isThumb:false},\n  {id:\"l_ring\",label:\"Manis\",value:10,isThumb:false},\n  {id:\"l_pinky\",label:\"Kelingking\",value:10,isThumb:false},\n];\nconst ALL=[...FL,...FR];\n\nfunction getAF(n){\n  const a=new Set();let r=Math.max(0,Math.min(99,n));\n  if(r>=50){a.add(\"l_thumb\");r-=50;}\n  for(let f of[\"l_index\",\"l_middle\",\"l_ring\",\"l_pinky\"])if(r>=10){a.add(f);r-=10;}\n  if(r>=5){a.add(\"r_thumb\");r-=5;}\n  for(let f of[\"r_index\",\"r_middle\",\"r_ring\",\"r_pinky\"])if(r>=1){a.add(f);r-=1;}\n  return a;\n}\nfunction calcVal(a){return ALL.reduce((s,f)=>s+(a.has(f.id)?f.value:0),0);}\n\nfunction genProb(op,level){\n  const rand=(mn,mx)=>Math.floor(Math.random()*(mx-mn+1))+mn;\n  let a,b,ans;\n  for(let i=0;i<300;i++){\n    if(op===\"+\"){\n      if(level===\"satuan\"){a=rand(1,9);b=rand(1,9);}\n      else if(level===\"puluhan\"){a=rand(10,60);b=rand(10,39);}\n      else{a=rand(1,70);b=rand(1,70);}\n      ans=a+b;\n    }else if(op===\"-\"){\n      if(level===\"satuan\"){a=rand(2,9);b=rand(1,8);}\n      else if(level===\"puluhan\"){a=rand(20,99);b=rand(10,90);}\n      else{a=rand(10,99);b=rand(1,90);}\n      ans=a-b;\n    }else if(op===\"\u00d7\"){\n      if(level===\"satuan\"){a=rand(2,9);b=rand(2,9);}\n      else if(level===\"puluhan\"){a=rand(2,9);b=rand(10,12);}\n      else{a=rand(2,9);b=rand(2,12);}\n      ans=a*b;\n    }else{\n      if(level===\"satuan\"){b=rand(2,9);a=b*rand(1,9);}\n      else if(level===\"puluhan\"){b=rand(2,9);a=b*rand(10,11);}\n      else{b=rand(2,9);a=b*rand(2,11);}\n      ans=a/b;\n    }\n    if(ans>=1&&ans<=99&&Number.isInteger(ans))return{a,b,ans,op};\n  }\n  return{a:5,b:3,ans:8,op:\"+\"};\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   STORAGE\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nasync function stGet(k){try{return localStorage.getItem(k);}catch{return null;}}\nasync function stSet(k,v){try{localStorage.setItem(k,v);}catch{}}\nasync function getLB(){try{const r=await stGet(\"chisa_lb3\");return r?JSON.parse(r):[];}catch{return[];}}\nasync function saveLB(d){await stSet(\"chisa_lb3\",JSON.stringify(d));}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   SOUND\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nlet _ctx=null;\nfunction getCtx(){if(!_ctx){try{_ctx=new(window.AudioContext||window.webkitAudioContext)();}catch{}}return _ctx;}\nfunction playSound(type,enabled){\n  if(!enabled)return;\n  const ctx=getCtx();if(!ctx)return;\n  try{\n    const play=(freq,dur,wave=\"sine\",vol=0.18,delay=0)=>{\n      const o=ctx.createOscillator(),g=ctx.createGain();\n      o.connect(g);g.connect(ctx.destination);\n      const t=ctx.currentTime+delay;\n      o.type=wave;o.frequency.setValueAtTime(freq,t);\n      g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);\n      o.start(t);o.stop(t+dur);\n    };\n    if(type===\"click\")play(600,0.07,\"sine\",0.1);\n    else if(type===\"correct\"){play(440,0.12);play(554,0.12,undefined,undefined,0.1);play(659,0.22,undefined,undefined,0.2);}\n    else if(type===\"wrong\"){play(200,0.22,\"sawtooth\",0.12);play(160,0.22,\"sawtooth\",0.08,0.1);}\n    else if(type===\"tick\")play(900,0.04,\"square\",0.06);\n    else if(type===\"urgentTick\"){play(1100,0.05,\"square\",0.1);play(1100,0.05,\"square\",0.1,0.1);}\n    else if(type===\"win\"){[523,659,784,1047].forEach((f,i)=>play(f,0.4,undefined,0.16,i*0.11));}\n    else if(type===\"countdown\")play(880,0.14,undefined,0.18);\n    else if(type===\"go\")play(1100,0.28,undefined,0.22);\n    else if(type===\"combo\"){[660,880,1100].forEach((f,i)=>play(f,0.18,undefined,0.14,i*0.07));}\n  }catch{}\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   THEMES\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nconst TH={\n  light:{\n    bg:\"#fff8f0\",bgGrad:\"linear-gradient(160deg,#fff3e0,#fff8f0)\",\n    card:\"#ffffff\",cardBorder:\"#ffe0b2\",cardShadow:\"0 4px 24px rgba(255,109,0,0.12)\",\n    text:\"#e65100\",subtext:\"#ff8a65\",muted:\"#ffb74d\",\n    accent:\"#ff6d00\",accent2:\"#e53935\",\n    accentGrad:\"linear-gradient(135deg,#ff6d00,#e53935)\",\n    accentGradHover:\"linear-gradient(135deg,#ff8c00,#ff1744)\",\n    inputBg:\"#fff8f0\",inputBorder:\"#ffcc80\",\n    navBg:\"rgba(255,255,255,0.96)\",navBorder:\"#ffe0b2\",\n    fingerOff:\"linear-gradient(160deg,#fff3e0,#ffd5a0)\",fingerBorderOff:\"#ffcc80\",\n    base:\"#fff3e0\",pill:\"#fff3e0\",pillBorder:\"#ffcc80\",pillText:\"#e65100\",\n    green:\"#00c853\",greenBg:\"#e8f5e9\",greenBorder:\"#a5d6a7\",greenText:\"#1b5e20\",\n    red:\"#d32f2f\",redBg:\"#ffebee\",redBorder:\"#ef9a9a\",redText:\"#b71c1c\",\n    shadow:\"rgba(255,109,0,0.15)\",\n    timerTrack:\"#ffe0b2\",\n    progressBar:\"linear-gradient(90deg,#ff6d00,#e53935)\",\n    badgeOn:\"rgba(255,109,0,0.15)\",badgeOff:\"rgba(0,0,0,0.03)\",\n  },\n  dark:{\n    bg:\"#110600\",bgGrad:\"linear-gradient(160deg,#1a0800,#2a1000)\",\n    card:\"#221000\",cardBorder:\"#4a2200\",cardShadow:\"0 4px 24px rgba(0,0,0,0.4)\",\n    text:\"#ffcc99\",subtext:\"#c87840\",muted:\"#7a4a20\",\n    accent:\"#ff6d00\",accent2:\"#ff3d00\",\n    accentGrad:\"linear-gradient(135deg,#ff6d00,#cc3000)\",\n    accentGradHover:\"linear-gradient(135deg,#ff8c00,#ff3d00)\",\n    inputBg:\"#1a0800\",inputBorder:\"#4a2200\",\n    navBg:\"rgba(20,8,0,0.97)\",navBorder:\"#4a2200\",\n    fingerOff:\"linear-gradient(160deg,#2a1200,#1a0800)\",fingerBorderOff:\"#5a2a00\",\n    base:\"#1a0800\",pill:\"#221000\",pillBorder:\"#4a2200\",pillText:\"#ffcc99\",\n    green:\"#69f0ae\",greenBg:\"#002a14\",greenBorder:\"#00693a\",greenText:\"#69f0ae\",\n    red:\"#ff5252\",redBg:\"#2a0008\",redBorder:\"#880022\",redText:\"#ff5252\",\n    shadow:\"rgba(0,0,0,0.5)\",\n    timerTrack:\"#3a1800\",\n    progressBar:\"linear-gradient(90deg,#ff6d00,#cc3000)\",\n    badgeOn:\"rgba(255,109,0,0.18)\",badgeOff:\"rgba(255,255,255,0.03)\",\n  }\n};\n\nconst AVATARS=[\"\ud83d\udc3c\",\"\ud83e\udd8a\",\"\ud83d\udc2f\",\"\ud83d\udc38\",\"\ud83e\udd81\",\"\ud83d\udc27\",\"\ud83e\udd8b\",\"\ud83d\udc19\",\"\ud83e\udd84\",\"\ud83d\udc09\",\"\ud83c\udf1f\",\"\ud83d\ude80\",\"\ud83c\udfaf\",\"\ud83c\udfc6\",\"\ud83e\udde0\",\"\ud83d\udc8e\"];\nconst OPS=[{id:\"+\",label:\"Tambah\",sym:\"+\",color:\"#ff6d00\"},{id:\"-\",label:\"Kurang\",sym:\"\u2212\",color:\"#e53935\"},{id:\"\u00d7\",label:\"Kali\",sym:\"\u00d7\",color:\"#7b1fa2\"},{id:\"\u00f7\",label:\"Bagi\",sym:\"\u00f7\",color:\"#0277bd\"}];\nconst LEVELS=[{id:\"satuan\",label:\"\ud83c\udf31 Mudah\",desc:\"1\u20139\"},{id:\"puluhan\",label:\"\ud83d\udd25 Sedang\",desc:\"10\u201399\"},{id:\"ratusan\",label:\"\u26a1 Susah\",desc:\"1\u201399\"}];\nconst TIME_OPTS=[{sec:10,label:\"10 det\",icon:\"\u26a1\"},{sec:30,label:\"30 det\",icon:\"\ud83d\udd50\"},{sec:60,label:\"1 menit\",icon:\"\u23f0\"}];\nconst MEDALS=[\"\ud83e\udd47\",\"\ud83e\udd48\",\"\ud83e\udd49\",\"4\ufe0f\u20e3\",\"5\ufe0f\u20e3\",\"6\ufe0f\u20e3\",\"7\ufe0f\u20e3\",\"8\ufe0f\u20e3\",\"9\ufe0f\u20e3\",\"\ud83d\udd1f\"];\nconst TOTAL=10;\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   CONFETTI\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction Confetti(){\n  const p=Array.from({length:30},(_,i)=>({\n    id:i,e:[\"\u2b50\",\"\ud83c\udf1f\",\"\u2728\",\"\ud83c\udf89\",\"\ud83c\udf8a\",\"\ud83c\udfc6\",\"\ud83d\udca5\",\"\ud83c\udf08\",\"\ud83c\udfaf\",\"\ud83d\udcab\",\"\ud83d\udd25\",\"\ud83d\udca1\"][i%12],\n    l:`${Math.random()*100}%`,d:`${Math.random()*1.2}s`,t:`${1.3+Math.random()*1}s`,s:`${14+Math.random()*18}px`\n  }));\n  return(\n    <div style={{position:\"fixed\",top:0,left:0,width:\"100%\",height:\"100%\",pointerEvents:\"none\",zIndex:9999}}>\n      {p.map(x=><div key={x.id} style={{position:\"absolute\",top:\"-30px\",left:x.l,fontSize:x.s,animation:`chisa-rain ${x.t} ${x.d} ease-in forwards`}}>{x.e}</div>)}\n    </div>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   GLOW PARTICLES\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction GlowParticles({th}){\n  const items=Array.from({length:8},(_,i)=>({\n    id:i,e:[\"\u2728\",\"\u2b50\",\"\ud83d\udcab\",\"\ud83c\udf1f\",\"\ud83c\udfaf\",\"\ud83d\udd90\ufe0f\",\"\ud83e\uddee\",\"\ud83d\udca1\"][i],\n    style:{position:\"fixed\",left:`${[8,20,78,90,15,70,45,55][i]}%`,top:`${[15,75,10,60,45,30,80,20][i]}%`,\n      fontSize:`${12+i%3*4}px`,opacity:0.1,pointerEvents:\"none\",zIndex:0,\n      animation:`chisa-float ${3+i%3*0.8}s ${i*0.3}s ease-in-out infinite`}\n  }));\n  return <>{items.map(p=><div key={p.id} style={p.style}>{p.e}</div>)}</>;\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   BOTTOM NAV\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction BottomNav({cur,onNav,th}){\n  const items=[{id:\"menu\",icon:\"\ud83c\udfe0\",label:\"Beranda\"},{id:\"leaderboard\",icon:\"\ud83c\udfc6\",label:\"Papan\"},{id:\"progress\",icon:\"\ud83d\udcca\",label:\"Progress\"},{id:\"settings\",icon:\"\u2699\ufe0f\",label:\"Setelan\"}];\n  return(\n    <div style={{position:\"fixed\",bottom:0,left:0,right:0,background:th.navBg,borderTop:`1.5px solid ${th.navBorder}`,display:\"flex\",justifyContent:\"space-around\",padding:\"6px 0 16px\",zIndex:100,backdropFilter:\"blur(12px)\"}}>\n      {items.map(({id,icon,label})=>(\n        <button key={id} onClick={()=>onNav(id)} style={{display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:2,background:\"none\",border:\"none\",cursor:\"pointer\",padding:\"6px 14px\",position:\"relative\"}}>\n          <div style={{fontSize:24,transition:\"all 0.2s cubic-bezier(.34,1.56,.64,1)\",transform:cur===id?\"scale(1.3) translateY(-2px)\":\"scale(1)\",filter:cur===id?`drop-shadow(0 3px 8px ${th.accent}80)`:\"none\"}}>{icon}</div>\n          <div style={{fontSize:9,fontWeight:800,color:cur===id?th.accent:th.muted,fontFamily:\"Nunito,sans-serif\",transition:\"color 0.2s\"}}>{label}</div>\n          {cur===id&&<div style={{position:\"absolute\",bottom:0,left:\"50%\",transform:\"translateX(-50%)\",width:20,height:3,borderRadius:2,background:th.accentGrad}}/>}\n        </button>\n      ))}\n    </div>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   TIMER RING - animated\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction TimerRing({progress,seconds,totalSec}){\n  const r=32,cx=40,cy=40,stroke=5.5,circ=2*Math.PI*r;\n  const pct=seconds/totalSec;\n  const color=pct>0.5?\"#00c853\":pct>0.25?\"#ffd600\":\"#ff1744\";\n  const urgent=pct<=0.25;\n  return(\n    <div style={{position:\"relative\",width:80,height:80,display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}>\n      {urgent&&<div style={{position:\"absolute\",width:80,height:80,borderRadius:\"50%\",border:`3px solid ${color}`,animation:\"chisa-pulse-ring 0.8s ease-out infinite\",opacity:0.5}}/>}\n      <svg width=\"80\" height=\"80\" style={{position:\"absolute\"}}>\n        <circle cx={cx} cy={cy} r={r} fill=\"none\" stroke={color+\"25\"} strokeWidth={stroke}/>\n        <circle cx={cx} cy={cy} r={r} fill=\"none\" stroke={color} strokeWidth={stroke}\n          strokeDasharray={circ} strokeDashoffset={circ*(1-progress)}\n          strokeLinecap=\"round\" transform={`rotate(-90 ${cx} ${cy})`}\n          style={{transition:\"stroke-dashoffset 0.25s linear,stroke 0.5s\"}}/>\n      </svg>\n      <div style={{textAlign:\"center\",zIndex:1}}>\n        <div style={{fontSize:22,fontWeight:900,color,fontFamily:\"Fredoka One,cursive\",lineHeight:1,animation:urgent?\"chisa-pulse 0.5s ease-in-out infinite\":\"none\"}}>{seconds}</div>\n        <div style={{fontSize:8,color:color+\"99\",fontWeight:700,letterSpacing:1}}>detik</div>\n      </div>\n    </div>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   FINGER\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction Finger({f,active,correct,wrong,onClick,th}){\n  const isA=active.has(f.id);\n  let bg=th.fingerOff,border=th.fingerBorderOff,glow=\"none\",textColor=th.muted;\n  if(correct){bg=\"linear-gradient(160deg,#69f0ae,#00c853)\";border=th.green;glow=`0 0 18px ${th.green}70`;textColor=\"#fff\";}\n  else if(wrong){bg=\"linear-gradient(160deg,#ff5252,#c62828)\";border=th.red;glow=`0 0 18px ${th.red}70`;textColor=\"#fff\";}\n  else if(isA){bg=th.accentGrad;border=th.accent;glow=`0 0 18px ${th.accent}60`;textColor=\"#fff\";}\n  return(\n    <button onClick={()=>onClick(f.id)} style={{display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:2,background:\"none\",border:\"none\",cursor:\"pointer\",padding:0,WebkitTapHighlightColor:\"transparent\"}}>\n      <div style={{\n        width:f.isThumb?36:28,height:f.isThumb?50:68,\n        borderRadius:f.isThumb?\"12px 4px 4px 12px\":\"14px 14px 4px 4px\",\n        background:isA?bg:th.fingerOff,\n        border:`2.5px solid ${isA?border:th.fingerBorderOff}`,\n        boxShadow:`${glow},0 4px 10px ${th.shadow}`,\n        transition:\"all 0.18s cubic-bezier(.34,1.56,.64,1)\",\n        transform:isA?\"translateY(-10px) scale(1.1)\":\"translateY(0) scale(1)\",\n        display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\n        fontSize:9,fontWeight:800,color:textColor,fontFamily:\"Nunito,sans-serif\",\n      }}>{f.value}</div>\n      <div style={{\n        width:f.isThumb?36:28,height:13,\n        background:isA?(correct?th.green:wrong?th.red:th.accent):th.fingerBorderOff,\n        borderRadius:\"0 0 8px 8px\",border:`2px solid ${isA?border:th.fingerBorderOff}`,borderTop:\"none\",\n        transition:\"all 0.18s\",\n      }}/>\n    </button>\n  );\n}\n\nfunction Hand({fingers,active,showResult,roundResult,onClick,side,th}){\n  return(\n    <div style={{display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:5}}>\n      <div style={{\n        fontSize:9,fontWeight:900,letterSpacing:2.5,color:th.accent,\n        textTransform:\"uppercase\",fontFamily:\"Fredoka One,cursive\",\n        background:`${th.accent}15`,padding:\"3px 10px\",borderRadius:20,\n      }}>{side===\"left\"?\"\u270b KIRI \u00d710\":\"\ud83e\udd1a KANAN \u00d71\"}</div>\n      <div style={{display:\"flex\",gap:3,alignItems:\"flex-end\"}}>\n        {fingers.map(f=>{\n          const isA=active.has(f.id),ok=roundResult===\"correct\";\n          return <Finger key={f.id} f={f} active={active} correct={showResult&&isA&&ok} wrong={showResult&&isA&&!ok} onClick={onClick} th={th}/>;\n        })}\n      </div>\n      <div style={{\n        width:side===\"left\"?176:156,height:32,\n        background:th.fingerOff,borderRadius:12,\n        border:`2px solid ${th.fingerBorderOff}`,\n        display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\n        fontSize:17,boxShadow:`0 3px 12px ${th.shadow}`,\n      }}>{side===\"left\"?\"\u270b\":\"\ud83e\udd1a\"}</div>\n    </div>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   SCORE BADGE\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction ScoreBadge({label,value,icon,color,th}){\n  return(\n    <div style={{background:th.card,borderRadius:16,padding:\"12px 10px\",border:`1.5px solid ${th.cardBorder}`,textAlign:\"center\",flex:1,boxShadow:th.cardShadow}}>\n      <div style={{fontSize:24,marginBottom:2}}>{icon}</div>\n      <div style={{fontSize:20,fontWeight:900,color,fontFamily:\"Fredoka One,cursive\",lineHeight:1}}>{value}</div>\n      <div style={{fontSize:9,color:th.muted,fontWeight:700,marginTop:2,textTransform:\"uppercase\",letterSpacing:1}}>{label}</div>\n    </div>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   TOGGLE SWITCH\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction Toggle({on,onToggle,th}){\n  return(\n    <button onClick={onToggle} style={{width:52,height:28,borderRadius:14,border:\"none\",cursor:\"pointer\",background:on?th.accentGrad:\"#ccc\",position:\"relative\",transition:\"background 0.3s\",flexShrink:0}}>\n      <div style={{position:\"absolute\",top:3,width:22,height:22,borderRadius:\"50%\",background:\"#fff\",boxShadow:\"0 2px 6px rgba(0,0,0,0.25)\",transition:\"left 0.25s cubic-bezier(.34,1.56,.64,1)\",left:on?26:3}}/>\n    </button>\n  );\n}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   MAIN APP\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nfunction App(){\n  const [screen,setScreen]=useState(\"splash\");\n  const [splashStep,setSplashStep]=useState(0);\n  const [playerName,setPlayerName]=useState(\"\");\n  const [nameInput,setNameInput]=useState(\"\");\n  const [avatar,setAvatar]=useState(\"\ud83d\udc3c\");\n  const [leaderboard,setLeaderboard]=useState([]);\n  const [allHistory,setAllHistory]=useState([]);\n  const [soundOn,setSoundOn]=useState(true);\n  const [theme,setTheme]=useState(\"light\");\n  const [selectedOps,setSelectedOps]=useState([\"+\"]);\n  const [level,setLevel]=useState(\"satuan\");\n  const [timeSec,setTimeSec]=useState(10);  // \u2190 TIME OPTION\n\n  // game state\n  const [phase,setPhase]=useState(\"idle\");\n  const [active,setActive]=useState(new Set());\n  const [problem,setProblem]=useState(null);\n  const [timeLeft,setTimeLeft]=useState(10);\n  const [showResult,setShowResult]=useState(false);\n  const [roundResult,setRoundResult]=useState(null);\n  const [score,setScore]=useState(0);\n  const [round,setRound]=useState(0);\n  const [combo,setCombo]=useState(0);\n  const [maxCombo,setMaxCombo]=useState(0);\n  const [roundHistory,setRoundHistory]=useState([]);\n  const [countdown,setCountdown]=useState(3);\n  const [flash,setFlash]=useState(null);\n  const [showConfetti,setShowConfetti]=useState(false);\n  const [streakAnim,setStreakAnim]=useState(false);\n\n  const timerRef=useRef(null);\n  const resultRef=useRef(null);\n  const stateRef=useRef({});\n  const th=TH[theme];\n  const snd=useCallback((t)=>playSound(t,soundOn),[soundOn]);\n  const currentValue=calcVal(active);\n\n  // keep stateRef fresh\n  useEffect(()=>{stateRef.current={round,score,combo,maxCombo,roundHistory,problem,currentValue,timeSec};}); \n\n  // inject CSS\n  useEffect(()=>{\n    if(document.getElementById(\"chisa-css\"))return;\n    const s=document.createElement(\"style\");\n    s.id=\"chisa-css\";\n    s.textContent=`\n      @import url('https://fonts.googleapis.com/css2?family=Fredoka+One&family=Nunito:wght@600;700;800;900&display=swap');\n      *{box-sizing:border-box;}\n      body{margin:0;padding:0;}\n      @keyframes chisa-pop{0%{transform:scale(0.15);opacity:0}65%{transform:scale(1.15)}100%{transform:scale(1);opacity:1}}\n      @keyframes chisa-bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}\n      @keyframes chisa-float{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-14px) rotate(3deg)}}\n      @keyframes chisa-floatin{0%{transform:translateY(28px);opacity:0}100%{transform:translateY(0);opacity:1}}\n      @keyframes chisa-rain{0%{transform:translateY(-20px) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}\n      @keyframes chisa-pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.12)}}\n      @keyframes chisa-pulse-ring{0%{transform:scale(1);opacity:0.6}100%{transform:scale(1.5);opacity:0}}\n      @keyframes chisa-shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}\n      @keyframes chisa-glow{0%,100%{box-shadow:0 0 12px rgba(255,109,0,0.4)}50%{box-shadow:0 0 28px rgba(255,109,0,0.8)}}\n      @keyframes chisa-slidein{0%{transform:translateY(20px);opacity:0}100%{transform:translateY(0);opacity:1}}\n      @keyframes chisa-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}\n      @keyframes chisa-streak{0%{transform:scale(1)}30%{transform:scale(1.4)}100%{transform:scale(1)}}\n      .chisa-pop{animation:chisa-pop 0.38s cubic-bezier(.34,1.56,.64,1) forwards}\n      .chisa-bounce{animation:chisa-bounce 1.4s ease-in-out infinite}\n      .chisa-floatin{animation:chisa-floatin 0.45s ease forwards}\n      .chisa-shake{animation:chisa-shake 0.35s ease}\n      .chisa-streak{animation:chisa-streak 0.4s ease}\n      .chisa-glow-btn{animation:chisa-glow 2s ease-in-out infinite}\n      button:active{opacity:0.85;transform:scale(0.96)!important}\n      input:focus{outline:none}\n    `;\n    document.head.appendChild(s);\n  },[]);\n\n  // SPLASH\n  useEffect(()=>{\n    if(screen!==\"splash\")return;\n    let idx=0;\n    const delays=[650,580,480,480,1000];\n    const next=()=>{\n      if(idx>=delays.length){\n        (async()=>{\n          const name=await stGet(\"chisa_name\");\n          const av=await stGet(\"chisa_avatar\")||\"\ud83d\udc3c\";\n          const th2=await stGet(\"chisa_theme\")||\"light\";\n          const snd2=await stGet(\"chisa_snd\");\n          const ts=parseInt(await stGet(\"chisa_time\")||\"10\");\n          const lb=await getLB();\n          const hist=JSON.parse(await stGet(\"chisa_hist\")||\"[]\");\n          setLeaderboard(lb);setAllHistory(hist);\n          setAvatar(av);setTheme(th2);\n          setSoundOn(snd2!==\"false\");\n          setTimeSec(ts||10);\n          if(name){setPlayerName(name);setScreen(\"menu\");}\n          else setScreen(\"register\");\n        })();\n        return;\n      }\n      setTimeout(()=>{setSplashStep(s=>s+1);idx++;next();},delays[idx]);\n    };\n    next();\n  },[]);\n\n  const handleRegister=async()=>{\n    if(!nameInput.trim())return;\n    const n=nameInput.trim();\n    await stSet(\"chisa_name\",n);await stSet(\"chisa_avatar\",avatar);\n    setPlayerName(n);setScreen(\"menu\");\n  };\n\n  // GAME LOGIC\n  const startRound=useCallback(()=>{\n    const op=selectedOps[Math.floor(Math.random()*selectedOps.length)];\n    const prob=genProb(op,level);\n    setProblem(prob);setActive(new Set());setTimeLeft(timeSec);\n    setShowResult(false);setRoundResult(null);setPhase(\"playing\");\n  },[selectedOps,level,timeSec]);\n\n  useEffect(()=>{\n    if(phase!==\"countdown\")return;\n    if(countdown===0){snd(\"go\");startRound();return;}\n    snd(\"countdown\");\n    const t=setTimeout(()=>setCountdown(c=>c-1),1000);\n    return()=>clearTimeout(t);\n  },[phase,countdown,startRound,snd]);\n\n  const endGame=useCallback(async(fs,fc,fh)=>{\n    clearTimeout(timerRef.current);clearTimeout(resultRef.current);\n    snd(\"win\");\n    const lb=await getLB();\n    const entry={name:playerName,avatar,score:fs,total:TOTAL,combo:fc,op:selectedOps.join(\"\"),level,timeSec,date:new Date().toLocaleDateString(\"id-ID\"),ts:Date.now()};\n    const newLb=[...lb,entry].sort((a,b)=>b.score-a.score||b.combo-a.combo).slice(0,10);\n    await saveLB(newLb);\n    const newH=[...allHistory,entry].slice(-50);\n    await stSet(\"chisa_hist\",JSON.stringify(newH));\n    setLeaderboard(newLb);setAllHistory(newH);\n    setPhase(\"idle\");setScreen(\"result\");\n  },[playerName,avatar,selectedOps,level,timeSec,allHistory,snd]);\n\n  const doTimeout=useCallback(()=>{\n    clearTimeout(timerRef.current);\n    const {round:r,score:s,maxCombo:mc,roundHistory:rh,problem:p,currentValue:cv}=stateRef.current;\n    snd(\"wrong\");setShowResult(true);setRoundResult(\"timeout\");\n    setFlash(\"red\");setTimeout(()=>setFlash(null),600);\n    const nr=r+1,nh=[...rh,{...(p||{}),got:cv,result:\"timeout\"}];\n    setRound(nr);setCombo(0);setRoundHistory(nh);\n    if(nr>=TOTAL)setTimeout(()=>endGame(s,mc,nh),2500);\n    else resultRef.current=setTimeout(startRound,2500);\n  },[snd,endGame,startRound]);\n\n  useEffect(()=>{\n    if(phase!==\"playing\"||showResult)return;\n    if(timeLeft<=0){doTimeout();return;}\n    const {timeSec:ts}=stateRef.current;\n    const pct=timeLeft/ts;\n    if(pct<=0.2)snd(\"urgentTick\");\n    else if(pct<=0.33)snd(\"tick\");\n    timerRef.current=setTimeout(()=>setTimeLeft(t=>t-1),1000);\n    return()=>clearTimeout(timerRef.current);\n  },[phase,showResult,timeLeft,doTimeout,snd]);\n\n  const handleCheck=()=>{\n    clearTimeout(timerRef.current);\n    const {round:r,score:s,combo:c,maxCombo:mc,roundHistory:rh,problem:p}=stateRef.current;\n    const correct=currentValue===p?.ans;\n    setShowResult(true);setRoundResult(correct?\"correct\":\"wrong\");\n    setFlash(correct?\"green\":\"red\");setTimeout(()=>setFlash(null),600);\n    const nr=r+1,ns=correct?s+1:s,nc=correct?c+1:0,nmc=Math.max(mc,nc);\n    const nh=[...rh,{...(p||{}),got:currentValue,result:correct?\"correct\":\"wrong\"}];\n    setScore(ns);setRound(nr);setCombo(nc);setMaxCombo(nmc);setRoundHistory(nh);\n    if(correct){\n      if(nc>=3){snd(\"combo\");setStreakAnim(true);setTimeout(()=>setStreakAnim(false),500);}\n      else snd(\"correct\");\n      setShowConfetti(nc>=5);setTimeout(()=>setShowConfetti(false),2000);\n    }else snd(\"wrong\");\n    if(nr>=TOTAL)setTimeout(()=>endGame(ns,nmc,nh),correct?1400:2500);\n    else resultRef.current=setTimeout(startRound,correct?1300:2500);\n  };\n\n  const handleStart=()=>{\n    if(!selectedOps.length)return;\n    setScore(0);setRound(0);setCombo(0);setMaxCombo(0);setRoundHistory([]);\n    setCountdown(3);setPhase(\"countdown\");setScreen(\"game\");\n  };\n  const handleStop=()=>{clearTimeout(timerRef.current);clearTimeout(resultRef.current);setPhase(\"idle\");setScreen(\"menu\");};\n  const toggleOp=(op)=>{snd(\"click\");setSelectedOps(prev=>prev.includes(op)?prev.length>1?prev.filter(o=>o!==op):prev:[...prev,op]);};\n  const toggleFinger=(id)=>{if(showResult||phase!==\"playing\")return;snd(\"click\");setActive(prev=>{const n=new Set(prev);n.has(id)?n.delete(id):n.add(id);return n;});};\n  const goTo=(s)=>{snd(\"click\");setScreen(s);};\n\n  const myGames=allHistory.filter(e=>e.name===playerName);\n  const bestScore=myGames.length?Math.max(...myGames.map(e=>e.score)):0;\n  const bestCombo=myGames.length?Math.max(...myGames.map(e=>e.combo||0)):0;\n  const avgScore=myGames.length?Math.round(myGames.reduce((s,e)=>s+e.score,0)/myGames.length*10)/10:0;\n  const stars=score>=9?3:score>=7?2:score>=5?1:0;\n  const timerProgress=timeLeft/timeSec;\n\n  /* \u2500\u2500 SPLASH \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"splash\"){\n    return(\n      <div style={{minHeight:\"100vh\",background:\"linear-gradient(135deg,#ff6d00 0%,#ff3d00 50%,#e53935 100%)\",display:\"flex\",flexDirection:\"column\",alignItems:\"center\",justifyContent:\"center\",fontFamily:\"Fredoka One,cursive\",position:\"relative\",overflow:\"hidden\"}}>\n        {/* decorative circles */}\n        <div style={{position:\"absolute\",width:500,height:500,borderRadius:\"50%\",background:\"rgba(255,255,255,0.04)\",top:-180,right:-120}}/>\n        <div style={{position:\"absolute\",width:300,height:300,borderRadius:\"50%\",background:\"rgba(255,255,255,0.06)\",bottom:-80,left:-80}}/>\n        <div style={{position:\"absolute\",width:180,height:180,borderRadius:\"50%\",background:\"rgba(255,255,255,0.05)\",top:\"35%\",left:\"5%\"}}/>\n        <div style={{position:\"absolute\",width:100,height:100,borderRadius:\"50%\",background:\"rgba(255,255,255,0.07)\",top:\"20%\",right:\"8%\"}}/>\n\n        {splashStep>=1&&<div className=\"chisa-pop\" style={{fontSize:100,marginBottom:8,filter:\"drop-shadow(0 12px 32px rgba(0,0,0,0.4))\"}}>\ud83d\udd90\ufe0f</div>}\n        {splashStep>=2&&(\n          <div className=\"chisa-pop\" style={{textAlign:\"center\"}}>\n            <div style={{fontSize:56,color:\"#fff\",textShadow:\"0 4px 24px rgba(0,0,0,0.3)\",letterSpacing:-2,lineHeight:1}}>\u6307\u73e0\u7b97</div>\n          </div>\n        )}\n        {splashStep>=3&&<div className=\"chisa-pop\" style={{fontSize:30,color:\"rgba(255,255,255,0.95)\",marginTop:4,letterSpacing:4}}>CHISANBOP</div>}\n        {splashStep>=4&&<div className=\"chisa-pop\" style={{fontSize:13,color:\"rgba(255,255,255,0.65)\",marginTop:8,letterSpacing:5,textTransform:\"uppercase\",fontFamily:\"Nunito,sans-serif\"}}>Sempoa Jari Super \ud83e\udde0</div>}\n        {splashStep>=5&&(\n          <div style={{marginTop:50,display:\"flex\",gap:12}}>\n            {[0,1,2].map(i=><div key={i} style={{width:11,height:11,borderRadius:\"50%\",background:\"rgba(255,255,255,0.9)\",animation:`chisa-bounce 0.9s ${i*0.2}s ease-in-out infinite`}}/>)}\n          </div>\n        )}\n        <div style={{position:\"absolute\",bottom:20,fontSize:11,color:\"rgba(255,255,255,0.35)\",letterSpacing:3,fontFamily:\"Nunito,sans-serif\"}}>\u00a9 2024 CHISANBOP EDU</div>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 REGISTER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"register\"){\n    return(\n      <div style={{minHeight:\"100vh\",background:\"linear-gradient(135deg,#ff6d00,#e53935)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",padding:20,fontFamily:\"Nunito,sans-serif\"}}>\n        <div className=\"chisa-pop\" style={{background:th.card,borderRadius:32,padding:\"28px 22px\",width:\"100%\",maxWidth:370,boxShadow:\"0 24px 64px rgba(0,0,0,0.35)\"}}>\n          <div style={{textAlign:\"center\",marginBottom:20}}>\n            <div style={{fontSize:60,marginBottom:8,animation:\"chisa-bounce 1.5s ease-in-out infinite\"}}>{avatar}</div>\n            <div style={{fontSize:26,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\"}}>Halo! \ud83d\udc4b</div>\n            <div style={{fontSize:13,color:th.subtext,marginTop:4}}>Pilih avatar & masukkan namamu</div>\n          </div>\n          <div style={{marginBottom:18}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:10}}>Pilih Avatar</div>\n            <div style={{display:\"flex\",flexWrap:\"wrap\",gap:8,justifyContent:\"center\"}}>\n              {AVATARS.map(av=>(\n                <button key={av} onClick={()=>{snd(\"click\");setAvatar(av);}} style={{width:44,height:44,borderRadius:12,fontSize:22,border:`2.5px solid ${av===avatar?th.accent:th.cardBorder}`,background:av===avatar?`${th.accent}22`:th.base,cursor:\"pointer\",transition:\"all 0.2s\",transform:av===avatar?\"scale(1.15)\":\"scale(1)\",boxShadow:av===avatar?`0 4px 12px ${th.accent}40`:\"none\"}}>\n                  {av}\n                </button>\n              ))}\n            </div>\n          </div>\n          <input value={nameInput} onChange={e=>setNameInput(e.target.value)} onKeyDown={e=>e.key===\"Enter\"&&handleRegister()}\n            placeholder=\"Nama kamu...\" maxLength={18}\n            style={{width:\"100%\",padding:\"14px 18px\",borderRadius:16,border:`2.5px solid ${nameInput?th.accent:th.inputBorder}`,fontSize:16,fontWeight:800,fontFamily:\"Nunito,sans-serif\",textAlign:\"center\",color:th.text,background:th.inputBg,marginBottom:14,display:\"block\",transition:\"border 0.2s\"}}\n            autoFocus/>\n          <button onClick={handleRegister} className=\"chisa-glow-btn\" style={{width:\"100%\",padding:\"16px\",borderRadius:18,border:\"none\",background:th.accentGrad,color:\"#fff\",fontSize:19,fontWeight:900,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",boxShadow:\"0 8px 24px rgba(255,109,0,0.5)\"}}>\n            \u25b6 MULAI BELAJAR!\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 SETTINGS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"settings\"){\n    const Row=({label,desc,right})=>(\n      <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"12px 0\",borderBottom:`1px solid ${th.cardBorder}30`}}>\n        <div><div style={{fontSize:14,fontWeight:800,color:th.text}}>{label}</div><div style={{fontSize:11,color:th.subtext,marginTop:2}}>{desc}</div></div>\n        {right}\n      </div>\n    );\n    return(\n      <div style={{minHeight:\"100vh\",background:th.bgGrad,fontFamily:\"Nunito,sans-serif\",padding:\"20px 16px\",paddingBottom:90}}>\n        <GlowParticles th={th}/>\n        <div style={{position:\"relative\",zIndex:1}}>\n          <div style={{fontSize:24,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\",marginBottom:18}}>\u2699\ufe0f Setelan</div>\n\n          {/* Profile */}\n          <div style={{background:th.card,borderRadius:24,padding:18,marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:14}}>\ud83d\udc64 Profil</div>\n            <div style={{display:\"flex\",alignItems:\"center\",gap:14,marginBottom:16}}>\n              <div style={{fontSize:46,background:th.base,borderRadius:18,width:62,height:62,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",border:`2px solid ${th.cardBorder}`,boxShadow:`0 4px 14px ${th.shadow}`}}>{avatar}</div>\n              <div>\n                <div style={{fontSize:19,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\"}}>{playerName}</div>\n                <div style={{fontSize:11,color:th.subtext}}>\ud83c\udfc6 Best: {bestScore}/{TOTAL} \u00b7 \u26a1 {bestCombo}x combo \u00b7 \ud83c\udfae {myGames.length}x main</div>\n              </div>\n            </div>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:10}}>Ganti Avatar</div>\n            <div style={{display:\"flex\",flexWrap:\"wrap\",gap:7}}>\n              {AVATARS.map(av=>(\n                <button key={av} onClick={async()=>{snd(\"click\");setAvatar(av);await stSet(\"chisa_avatar\",av);}} style={{width:42,height:42,borderRadius:11,fontSize:21,border:`2.5px solid ${av===avatar?th.accent:th.cardBorder}`,background:av===avatar?`${th.accent}20`:th.base,cursor:\"pointer\",transition:\"all 0.2s\",transform:av===avatar?\"scale(1.14)\":\"scale(1)\"}}>\n                  {av}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Preferences */}\n          <div style={{background:th.card,borderRadius:24,padding:\"4px 18px 18px\",marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",padding:\"14px 0 4px\"}}>\ud83c\udfae Preferensi</div>\n            <Row label=\"\ud83d\udd0a Efek Suara\" desc=\"Klik, benar, salah, combo, waktu\" right={<Toggle on={soundOn} onToggle={async()=>{const v=!soundOn;setSoundOn(v);await stSet(\"chisa_snd\",String(v));if(v)playSound(\"click\",true);}} th={th}/>}/>\n            <Row label=\"\ud83c\udfa8 Mode Gelap\" desc=\"Tema malam yang ramah mata\" right={<Toggle on={theme===\"dark\"} onToggle={async()=>{const v=theme===\"dark\"?\"light\":\"dark\";setTheme(v);await stSet(\"chisa_theme\",v);}} th={th}/>}/>\n          </div>\n\n          {/* Time option in settings too */}\n          <div style={{background:th.card,borderRadius:24,padding:18,marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:12}}>\u23f1\ufe0f Default Waktu per Soal</div>\n            <div style={{display:\"flex\",gap:10}}>\n              {TIME_OPTS.map(({sec,label,icon})=>(\n                <button key={sec} onClick={async()=>{snd(\"click\");setTimeSec(sec);await stSet(\"chisa_time\",String(sec));}} style={{flex:1,padding:\"12px 6px\",borderRadius:16,border:`2.5px solid ${timeSec===sec?th.accent:th.cardBorder}`,background:timeSec===sec?`${th.accent}18`:th.base,color:timeSec===sec?th.accent:th.muted,fontWeight:900,fontSize:13,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",textAlign:\"center\",transition:\"all 0.2s\",boxShadow:timeSec===sec?`0 4px 14px ${th.accent}30`:\"none\"}}>\n                  <div style={{fontSize:22,marginBottom:3}}>{icon}</div>\n                  {label}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Guide */}\n          <div style={{background:th.card,borderRadius:24,padding:18,marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:12}}>\ud83d\udcd6 Panduan Jari</div>\n            {[[\"\u270b Tangan Kiri\",\"Ibu jari = 50 \u00b7 Telunjuk/Tengah/Manis/Kelingking = 10 masing-masing\"],[\"\ud83e\udd1a Tangan Kanan\",\"Ibu jari = 5 \u00b7 Telunjuk/Tengah/Manis/Kelingking = 1 masing-masing\"]].map(([t,d])=>(\n              <div key={t} style={{padding:\"11px 14px\",borderRadius:14,background:th.base,border:`1.5px solid ${th.cardBorder}`,marginBottom:8}}>\n                <div style={{fontSize:13,fontWeight:800,color:th.text,marginBottom:3}}>{t}</div>\n                <div style={{fontSize:11,color:th.subtext,lineHeight:1.6}}>{d}</div>\n              </div>\n            ))}\n            <div style={{fontSize:11,color:th.muted,textAlign:\"center\",marginTop:6,fontWeight:700}}>Max Chisanbop 2 tangan = <span style={{color:th.accent,fontSize:13}}>99</span></div>\n          </div>\n\n          <button onClick={async()=>{if(!window.confirm(\"Reset semua data?\"))return;await stSet(\"chisa_lb3\",\"[]\");await stSet(\"chisa_hist\",\"[]\");setLeaderboard([]);setAllHistory([]);}} style={{width:\"100%\",padding:\"13px\",borderRadius:16,border:`2px solid ${th.redBorder}`,background:th.redBg,color:th.red,fontSize:14,fontWeight:800,cursor:\"pointer\",fontFamily:\"Nunito,sans-serif\"}}>\n            \ud83d\uddd1\ufe0f Reset Semua Data\n          </button>\n        </div>\n        <BottomNav cur=\"settings\" onNav={goTo} th={th}/>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 PROGRESS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"progress\"){\n    const opStats=OPS.map(op=>{const gs=myGames.filter(g=>g.op.includes(op.id));return{...op,games:gs.length,avg:gs.length?Math.round(gs.reduce((s,g)=>s+g.score,0)/gs.length*10)/10:0};});\n    const streak7=myGames.slice(-7).filter(g=>g.score>=5).length;\n    return(\n      <div style={{minHeight:\"100vh\",background:th.bgGrad,fontFamily:\"Nunito,sans-serif\",padding:\"20px 16px\",paddingBottom:90}}>\n        <GlowParticles th={th}/>\n        <div style={{position:\"relative\",zIndex:1}}>\n          <div style={{fontSize:24,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\",marginBottom:16}}>\ud83d\udcca Progress Kamu</div>\n\n          <div style={{display:\"grid\",gridTemplateColumns:\"1fr 1fr\",gap:10,marginBottom:14}}>\n            {[[\"\ud83c\udfc6\",\"Best\",`${bestScore}/${TOTAL}`,\"#ff6d00\"],[\"\u26a1\",\"Combo\",`${bestCombo}x`,\"#7b1fa2\"],[\"\ud83c\udfae\",\"Main\",`${myGames.length}x`,\"#0277bd\"],[\"\ud83d\udcc8\",\"Rata\u00b2\",`${avgScore}/${TOTAL}`,\"#00897b\"]].map(([icon,label,val,color])=>(\n              <ScoreBadge key={label} label={label} value={val} icon={icon} color={color} th={th}/>\n            ))}\n          </div>\n\n          {/* Streak chart */}\n          <div style={{background:th.card,borderRadius:24,padding:18,marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{display:\"flex\",justifyContent:\"space-between\",alignItems:\"center\",marginBottom:14}}>\n              <div style={{fontSize:11,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\"}}>\ud83d\udd25 7 Game Terakhir</div>\n              <div style={{fontSize:12,fontWeight:800,color:th.accent,background:`${th.accent}18`,borderRadius:10,padding:\"3px 10px\"}}>{streak7}/7 skor \u22655</div>\n            </div>\n            <div style={{display:\"flex\",gap:6,alignItems:\"flex-end\",height:60}}>\n              {Array.from({length:7}).map((_,i)=>{\n                const g=myGames.slice(-7)[i];\n                const h=g?Math.round(g.score/TOTAL*100):0;\n                return(\n                  <div key={i} style={{flex:1,display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:3}}>\n                    <div style={{fontSize:10,fontWeight:800,color:g?th.text:th.muted}}>{g?g.score:\"\u00b7\"}</div>\n                    <div style={{width:\"100%\",height:40,borderRadius:8,background:th.base,display:\"flex\",alignItems:\"flex-end\",overflow:\"hidden\"}}>\n                      <div style={{width:\"100%\",height:`${h}%`,background:g?(g.score>=7?th.accentGrad:g.score>=5?`linear-gradient(135deg,${th.muted},${th.accent})`:`linear-gradient(135deg,${th.redBorder},${th.red})`):th.base,borderRadius:8,transition:\"height 1s ease\"}}/>\n                    </div>\n                  </div>\n                );\n              })}\n            </div>\n          </div>\n\n          {/* Per op */}\n          <div style={{background:th.card,borderRadius:24,padding:18,marginBottom:14,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:11,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:14}}>\ud83d\udcd0 Per Operasi</div>\n            {opStats.map(({id,label,sym,color,games,avg})=>(\n              <div key={id} style={{marginBottom:14}}>\n                <div style={{display:\"flex\",justifyContent:\"space-between\",marginBottom:5}}>\n                  <span style={{fontWeight:800,color:th.text,fontSize:14}}><span style={{color,fontSize:16}}>{sym}</span> {label}</span>\n                  <span style={{fontSize:11,color:th.muted,background:`${color}18`,borderRadius:8,padding:\"2px 8px\",fontWeight:700}}>{games} main \u00b7 avg {avg}/{TOTAL}</span>\n                </div>\n                <div style={{height:10,borderRadius:6,background:th.base,overflow:\"hidden\"}}>\n                  <div style={{height:\"100%\",borderRadius:6,background:`linear-gradient(90deg,${color},${color}80)`,width:`${games?avg/TOTAL*100:0}%`,transition:\"width 1.2s ease\"}}/>\n                </div>\n              </div>\n            ))}\n          </div>\n\n          {/* Badges */}\n          <div style={{background:th.card,borderRadius:24,padding:18,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:11,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:14}}>\ud83c\udf96\ufe0f Lencana</div>\n            <div style={{display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:8}}>\n              {[\n                [myGames.length>=1,\"\ud83c\udf31\",\"Pemula\",\"1 game\"],\n                [myGames.length>=5,\"\ud83d\udd25\",\"Rajin\",\"5 game\"],\n                [myGames.length>=20,\"\ud83d\udcaa\",\"Veteran\",\"20 game\"],\n                [bestScore>=TOTAL,\"\ud83c\udfc6\",\"Sempurna\",\"Nilai 10/10\"],\n                [bestCombo>=5,\"\u26a1\",\"Combo Pro\",\"5\u00d7 beruntun\"],\n                [myGames.filter(g=>g.timeSec===10).length>=5,\"\u26a1\",\"Speed\",\"5\u00d7 mode cepat\"],\n                [myGames.filter(g=>g.level===\"puluhan\").length>=3,\"\ud83d\udd22\",\"Puluhan\",\"3\u00d7 sedang\"],\n                [myGames.filter(g=>g.op.includes(\"\u00d7\")).length>=1,\"\u2716\ufe0f\",\"Kali Jago\",\"Main kali\"],\n                [myGames.filter(g=>g.op.includes(\"\u00f7\")).length>=1,\"\u2797\",\"Bagi Jago\",\"Main bagi\"],\n              ].map(([earned,icon,label,req])=>(\n                <div key={label} style={{padding:\"10px 6px\",borderRadius:14,textAlign:\"center\",background:earned?th.badgeOn:th.badgeOff,border:`2px solid ${earned?th.accent:th.cardBorder}`,opacity:earned?1:0.38,transition:\"all 0.3s\"}}>\n                  <div style={{fontSize:26,marginBottom:4,filter:earned?\"none\":\"grayscale(1)\"}}>{icon}</div>\n                  <div style={{fontSize:10,fontWeight:800,color:th.text,lineHeight:1.2}}>{label}</div>\n                  <div style={{fontSize:9,color:th.muted,marginTop:2}}>{req}</div>\n                </div>\n              ))}\n            </div>\n          </div>\n        </div>\n        <BottomNav cur=\"progress\" onNav={goTo} th={th}/>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 LEADERBOARD \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"leaderboard\"){\n    return(\n      <div style={{minHeight:\"100vh\",background:th.bgGrad,fontFamily:\"Nunito,sans-serif\",padding:\"20px 16px\",paddingBottom:90}}>\n        <GlowParticles th={th}/>\n        <div style={{position:\"relative\",zIndex:1}}>\n          <div style={{fontSize:24,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\",marginBottom:16}}>\ud83c\udfc6 Hall of Fame</div>\n          {leaderboard.length===0?(\n            <div style={{textAlign:\"center\",padding:60,color:th.muted}}>\n              <div style={{fontSize:56,marginBottom:14,animation:\"chisa-bounce 1.5s ease-in-out infinite\"}}>\ud83c\udf1f</div>\n              <div style={{fontSize:18,fontWeight:900,color:th.text}}>Belum ada skor!</div>\n              <div style={{fontSize:13,marginTop:6}}>Ayo main dulu!</div>\n            </div>\n          ):(\n            <div style={{display:\"flex\",flexDirection:\"column\",gap:10}}>\n              {leaderboard.map((entry,i)=>{\n                const isMe=entry.name===playerName;\n                const pct=Math.round(entry.score/entry.total*100);\n                return(\n                  <div key={i} className=\"chisa-floatin\" style={{background:i===0?th.accentGrad:isMe?`${th.accent}14`:th.card,borderRadius:20,padding:\"14px 16px\",border:`2px solid ${isMe&&i!==0?th.accent:th.cardBorder}`,boxShadow:i<3?`0 8px 24px ${th.shadow}`:th.cardShadow,display:\"flex\",alignItems:\"center\",gap:12,animationDelay:`${i*0.06}s`}}>\n                    <div style={{fontSize:26,flexShrink:0}}>{MEDALS[i]}</div>\n                    <div style={{flex:1,minWidth:0}}>\n                      <div style={{fontSize:15,fontWeight:900,color:i===0?\"#fff\":th.text,fontFamily:\"Fredoka One,cursive\",display:\"flex\",alignItems:\"center\",gap:6,flexWrap:\"wrap\"}}>\n                        <span>{entry.avatar||\"\ud83d\udc3c\"}</span>{entry.name}\n                        {isMe&&<span style={{fontSize:10,background:th.accent,color:\"#fff\",borderRadius:7,padding:\"2px 7px\"}}>KAMU</span>}\n                      </div>\n                      <div style={{fontSize:10,color:i===0?\"rgba(255,255,255,0.75)\":th.subtext,marginTop:2}}>{entry.op||\"+\"} \u00b7 {entry.level} \u00b7 {entry.timeSec||10}det \u00b7 {entry.date}</div>\n                      <div style={{height:5,borderRadius:4,background:i===0?\"rgba(255,255,255,0.25)\":th.base,marginTop:6,overflow:\"hidden\"}}>\n                        <div style={{height:\"100%\",borderRadius:4,background:i===0?\"#fff\":th.progressBar,width:`${pct}%`,transition:\"width 1s ease\"}}/>\n                      </div>\n                    </div>\n                    <div style={{textAlign:\"center\",flexShrink:0}}>\n                      <div style={{fontSize:24,fontWeight:900,fontFamily:\"Fredoka One,cursive\",color:i===0?\"#fff\":th.accent}}>{entry.score}<span style={{fontSize:12,opacity:0.6}}>/{entry.total}</span></div>\n                      {(entry.combo||0)>0&&<div style={{fontSize:10,color:i===0?\"rgba(255,255,255,0.7)\":th.subtext}}>\u26a1{entry.combo}x</div>}\n                    </div>\n                  </div>\n                );\n              })}\n            </div>\n          )}\n        </div>\n        <BottomNav cur=\"leaderboard\" onNav={goTo} th={th}/>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 RESULT \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"result\"){\n    const msg=score===TOTAL?\"Sempurna! Genius! \ud83e\udde0\":score>=8?\"Luar Biasa! \ud83d\udd25\":score>=6?\"Bagus Banget! \ud83d\udcaa\":score>=4?\"Terus Semangat! \ud83c\udf1f\":\"Ayo Coba Lagi! \ud83d\udcaa\";\n    return(\n      <div style={{minHeight:\"100vh\",background:th.accentGrad,fontFamily:\"Nunito,sans-serif\",padding:\"20px 16px\",display:\"flex\",flexDirection:\"column\",alignItems:\"center\"}}>\n        <Confetti/>\n        <div className=\"chisa-pop\" style={{background:th.card,borderRadius:32,padding:\"26px 22px\",width:\"100%\",maxWidth:420,textAlign:\"center\",boxShadow:\"0 24px 64px rgba(0,0,0,0.35)\",marginTop:10}}>\n          <div style={{fontSize:64,marginBottom:6,animation:\"chisa-bounce 1.5s ease-in-out infinite\"}}>{score===TOTAL?\"\ud83c\udfc6\":score>=8?\"\ud83e\udd47\":score>=6?\"\ud83e\udd48\":\"\ud83e\udd49\"}</div>\n          <div style={{fontSize:11,fontWeight:800,color:th.muted,letterSpacing:3,textTransform:\"uppercase\"}}>Hasil Latihan</div>\n          <div style={{fontSize:66,fontWeight:900,color:th.accent,fontFamily:\"Fredoka One,cursive\",lineHeight:1.05}}>{score}<span style={{fontSize:28,color:th.muted}}>/{TOTAL}</span></div>\n          <div style={{fontSize:38,letterSpacing:6,margin:\"8px 0\"}}>{[1,2,3].map(i=><span key={i} style={{opacity:i<=stars?1:0.2,transition:\"opacity 0.5s\",transitionDelay:`${i*0.2}s`}}>{i<=stars?\"\u2b50\":\"\u2606\"}</span>)}</div>\n          <div style={{fontSize:16,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\",marginBottom:14}}>{msg}</div>\n\n          {/* Progress bar */}\n          <div style={{height:12,borderRadius:8,background:th.base,marginBottom:16,overflow:\"hidden\",position:\"relative\"}}>\n            <div style={{position:\"absolute\",height:\"100%\",borderRadius:8,background:th.progressBar,width:`${Math.round(score/TOTAL*100)}%`,transition:\"width 1.5s cubic-bezier(.34,1.1,.64,1)\"}}/>\n          </div>\n\n          {/* Stats row */}\n          <div style={{display:\"flex\",gap:8,marginBottom:16}}>\n            {[[\"\u26a1\",\"Combo\",`${maxCombo}x`,\"#7b1fa2\"],[\"\u2705\",\"Benar\",score,\"#00c853\"],[\"\u274c\",\"Salah\",TOTAL-score,\"#d32f2f\"],[\"\u23f1\ufe0f\",\"Waktu\",`${timeSec}det`,\"#0277bd\"]].map(([icon,label,val,color])=>(\n              <div key={label} style={{flex:1,background:th.base,borderRadius:14,padding:\"10px 4px\",border:`1.5px solid ${th.cardBorder}`}}>\n                <div style={{fontSize:18}}>{icon}</div>\n                <div style={{fontSize:18,fontWeight:900,color,fontFamily:\"Fredoka One,cursive\",lineHeight:1}}>{val}</div>\n                <div style={{fontSize:9,color:th.muted,fontWeight:700}}>{label}</div>\n              </div>\n            ))}\n          </div>\n\n          {/* History chips */}\n          <div style={{display:\"flex\",flexWrap:\"wrap\",gap:5,justifyContent:\"center\",marginBottom:16}}>\n            {roundHistory.map((h,i)=>(\n              <div key={i} style={{padding:\"4px 9px\",borderRadius:9,fontSize:11,fontWeight:700,background:h.result===\"correct\"?th.greenBg:th.redBg,color:h.result===\"correct\"?th.greenText:th.redText,border:`1.5px solid ${h.result===\"correct\"?th.greenBorder:th.redBorder}`}}>{h.a}{h.op}{h.b}={h.ans}</div>\n            ))}\n          </div>\n\n          <button onClick={()=>{snd(\"click\");setScreen(\"game\");handleStart();}} className=\"chisa-glow-btn\" style={{width:\"100%\",padding:\"16px\",borderRadius:18,border:\"none\",background:th.accentGrad,color:\"#fff\",fontSize:19,fontWeight:900,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",boxShadow:\"0 8px 24px rgba(255,109,0,0.5)\",marginBottom:10}}>\ud83d\udd04 Main Lagi!</button>\n          <div style={{display:\"flex\",gap:8}}>\n            {[[\"\ud83c\udfe0\",\"Menu\",\"menu\"],[\"\ud83c\udfc6\",\"Papan\",\"leaderboard\"],[\"\ud83d\udcca\",\"Stat\",\"progress\"]].map(([icon,label,target])=>(\n              <button key={target} onClick={()=>goTo(target)} style={{flex:1,padding:\"11px\",borderRadius:13,border:`2px solid ${th.cardBorder}`,background:th.base,color:th.text,fontSize:12,fontWeight:800,cursor:\"pointer\",fontFamily:\"Nunito,sans-serif\"}}>{icon} {label}</button>\n            ))}\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 MENU \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"menu\"){\n    return(\n      <div style={{minHeight:\"100vh\",background:th.bgGrad,fontFamily:\"Nunito,sans-serif\",padding:\"18px 16px\",paddingBottom:90,position:\"relative\"}}>\n        <GlowParticles th={th}/>\n        <div style={{position:\"relative\",zIndex:1}}>\n          {/* Header */}\n          <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:16}}>\n            <div style={{display:\"flex\",alignItems:\"center\",gap:12}}>\n              <div style={{fontSize:40,filter:`drop-shadow(0 4px 10px ${th.accent}50)`}}>{avatar}</div>\n              <div>\n                <div style={{fontSize:22,fontWeight:900,color:th.text,fontFamily:\"Fredoka One,cursive\",lineHeight:1}}>Halo, {playerName}!</div>\n                <div style={{fontSize:10,color:th.subtext,letterSpacing:2}}>\u6307\u73e0\u7b97 \u00b7 CHISANBOP</div>\n              </div>\n            </div>\n            <button onClick={()=>goTo(\"settings\")} style={{width:42,height:42,borderRadius:14,border:`1.5px solid ${th.cardBorder}`,background:th.card,fontSize:20,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",boxShadow:th.cardShadow}}>\u2699\ufe0f</button>\n          </div>\n\n          {/* Stats banner */}\n          {myGames.length>0&&(\n            <div style={{background:th.accentGrad,borderRadius:22,padding:\"14px 20px\",marginBottom:14,display:\"flex\",justifyContent:\"space-around\",boxShadow:`0 8px 24px ${th.accent}40`}}>\n              {[[\"\ud83c\udfc6\",\"Best\",`${bestScore}/${TOTAL}`],[\"\u26a1\",\"Combo\",`${bestCombo}x`],[\"\ud83c\udfae\",\"Main\",`${myGames.length}x`],[\"\ud83d\udcc8\",\"Avg\",`${avgScore}`]].map(([icon,label,val])=>(\n                <div key={label} style={{textAlign:\"center\",color:\"#fff\"}}>\n                  <div style={{fontSize:17}}>{icon}</div>\n                  <div style={{fontSize:18,fontWeight:900,fontFamily:\"Fredoka One,cursive\",lineHeight:1}}>{val}</div>\n                  <div style={{fontSize:9,opacity:0.75,textTransform:\"uppercase\",letterSpacing:1}}>{label}</div>\n                </div>\n              ))}\n            </div>\n          )}\n\n          {/* Operation selector */}\n          <div style={{background:th.card,borderRadius:22,padding:18,marginBottom:12,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:12}}>\u2699\ufe0f Pilih Operasi</div>\n            <div style={{display:\"flex\",gap:8}}>\n              {OPS.map(({id,label,sym,color})=>(\n                <button key={id} onClick={()=>toggleOp(id)} style={{flex:1,padding:\"12px 4px\",borderRadius:16,border:`2.5px solid ${selectedOps.includes(id)?color:th.cardBorder}`,background:selectedOps.includes(id)?`${color}18`:th.base,color:selectedOps.includes(id)?color:th.muted,fontWeight:900,fontSize:24,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",lineHeight:1.25,transition:\"all 0.2s\",boxShadow:selectedOps.includes(id)?`0 4px 16px ${color}35`:\"none\"}}>\n                  {sym}<br/><span style={{fontSize:9,fontWeight:700}}>{label}</span>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Level selector */}\n          <div style={{background:th.card,borderRadius:22,padding:18,marginBottom:12,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:12}}>\ud83c\udfaf Tingkat Kesulitan</div>\n            <div style={{display:\"flex\",gap:8}}>\n              {LEVELS.map(({id,label,desc})=>(\n                <button key={id} onClick={()=>{snd(\"click\");setLevel(id);}} style={{flex:1,padding:\"12px 4px\",borderRadius:16,border:`2.5px solid ${level===id?th.accent:th.cardBorder}`,background:level===id?`${th.accent}18`:th.base,color:level===id?th.accent:th.muted,fontWeight:800,fontSize:12,cursor:\"pointer\",fontFamily:\"Nunito,sans-serif\",lineHeight:1.5,transition:\"all 0.2s\",boxShadow:level===id?`0 4px 16px ${th.accent}30`:\"none\"}}>\n                  {label}<br/><span style={{fontSize:10,opacity:0.7}}>{desc}</span>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* TIME SELECTOR \u2014 NEW! */}\n          <div style={{background:th.card,borderRadius:22,padding:18,marginBottom:16,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow}}>\n            <div style={{fontSize:10,fontWeight:800,color:th.muted,letterSpacing:2,textTransform:\"uppercase\",marginBottom:12}}>\u23f1\ufe0f Waktu per Soal</div>\n            <div style={{display:\"flex\",gap:8}}>\n              {TIME_OPTS.map(({sec,label,icon})=>(\n                <button key={sec} onClick={async()=>{snd(\"click\");setTimeSec(sec);await stSet(\"chisa_time\",String(sec));}} style={{flex:1,padding:\"14px 6px\",borderRadius:16,border:`2.5px solid ${timeSec===sec?th.accent:th.cardBorder}`,background:timeSec===sec?`${th.accent}18`:th.base,color:timeSec===sec?th.accent:th.muted,fontWeight:900,fontSize:14,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",textAlign:\"center\",transition:\"all 0.2s\",boxShadow:timeSec===sec?`0 4px 16px ${th.accent}30`:\"none\",position:\"relative\"}}>\n                  <div style={{fontSize:26,marginBottom:4}}>{icon}</div>\n                  {label}\n                  {timeSec===sec&&<div style={{position:\"absolute\",top:-6,right:-6,width:18,height:18,borderRadius:\"50%\",background:th.accentGrad,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:10}}>\u2713</div>}\n                </button>\n              ))}\n            </div>\n            <div style={{fontSize:11,color:th.subtext,marginTop:10,textAlign:\"center\",fontWeight:600}}>\n              {timeSec===10?\"\u26a1 Mode cepat \u2014 cocok untuk latihan intensif!\":timeSec===30?\"\ud83d\udd50 Mode standar \u2014 waktu cukup untuk berpikir\":\"\u23f0 Mode santai \u2014 bagus untuk pemula & adik kecil! \ud83e\udd70\"}\n            </div>\n          </div>\n\n          <button onClick={handleStart} className=\"chisa-glow-btn chisa-bounce\" style={{width:\"100%\",padding:\"20px\",borderRadius:22,border:\"none\",background:th.accentGrad,color:\"#fff\",fontSize:24,fontWeight:900,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",boxShadow:`0 10px 30px ${th.accent}55`,marginBottom:12}}>\n            \ud83d\ude80 MULAI LATIHAN!\n          </button>\n\n          <div style={{background:th.card,borderRadius:16,padding:\"11px 16px\",border:`1.5px solid ${th.cardBorder}`,fontSize:11,color:th.subtext,lineHeight:2}}>\n            <b style={{color:th.accent}}>\ud83d\udcd6 Panduan: </b>\n            Kiri: Ibu=<b style={{color:th.accent}}>50</b> \u00b7 4jari=<b style={{color:th.accent}}>10</b> &nbsp;|&nbsp; Kanan: Ibu=<b style={{color:th.accent}}>5</b> \u00b7 4jari=<b style={{color:th.accent}}>1</b>\n          </div>\n        </div>\n        <BottomNav cur=\"menu\" onNav={goTo} th={th}/>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 COUNTDOWN \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  if(screen===\"game\"&&phase===\"countdown\"){\n    return(\n      <div style={{minHeight:\"100vh\",background:th.accentGrad,display:\"flex\",flexDirection:\"column\",alignItems:\"center\",justifyContent:\"center\",fontFamily:\"Fredoka One,cursive\",position:\"relative\",overflow:\"hidden\"}}>\n        <div style={{position:\"absolute\",width:400,height:400,borderRadius:\"50%\",background:\"rgba(255,255,255,0.06)\",top:-100,right:-80}}/>\n        <div style={{position:\"absolute\",width:250,height:250,borderRadius:\"50%\",background:\"rgba(255,255,255,0.04)\",bottom:-60,left:-60}}/>\n        <div style={{fontSize:14,letterSpacing:5,color:\"rgba(255,255,255,0.8)\",textTransform:\"uppercase\",marginBottom:16,fontFamily:\"Nunito,sans-serif\"}}>Siap-siap!</div>\n        <div key={countdown} className=\"chisa-pop\" style={{fontSize:140,fontWeight:900,color:\"#fff\",lineHeight:1,textShadow:\"0 10px 40px rgba(0,0,0,0.35)\"}}>{countdown===0?\"GO!\":countdown}</div>\n        <div style={{marginTop:24,display:\"flex\",gap:10}}>{selectedOps.map(op=><span key={op} style={{padding:\"8px 18px\",borderRadius:14,background:\"rgba(255,255,255,0.2)\",color:\"#fff\",fontSize:24,fontWeight:900,backdropFilter:\"blur(8px)\"}}>{op}</span>)}</div>\n        <div style={{marginTop:12,fontSize:14,color:\"rgba(255,255,255,0.7)\",fontFamily:\"Nunito,sans-serif\"}}>{LEVELS.find(l=>l.id===level)?.label} \u00b7 {TOTAL} soal \u00b7 {timeSec} detik/soal</div>\n      </div>\n    );\n  }\n\n  /* \u2500\u2500 GAME \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n  const flashBg=flash===\"green\"?th.greenBg:flash===\"red\"?th.redBg:th.bgGrad;\n  return(\n    <div style={{minHeight:\"100vh\",background:flashBg,transition:\"background 0.25s\",fontFamily:\"Nunito,sans-serif\",display:\"flex\",flexDirection:\"column\",alignItems:\"center\",padding:\"12px 12px\",gap:8}}>\n      {showConfetti&&<Confetti/>}\n\n      {/* Top bar */}\n      <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",width:\"100%\",maxWidth:480}}>\n        <div style={{padding:\"7px 14px\",borderRadius:14,background:th.accentGrad,fontSize:13,fontWeight:900,color:\"#fff\",fontFamily:\"Fredoka One,cursive\",boxShadow:`0 4px 14px ${th.accent}50`}}>\n          \u2705 {score}<span style={{opacity:0.7,fontSize:11}}>/{TOTAL}</span>\n          {combo>=2&&(\n            <span className={streakAnim?\"chisa-streak\":\"\"} style={{marginLeft:7,fontSize:11,background:\"rgba(255,255,255,0.25)\",borderRadius:8,padding:\"2px 7px\"}}>\u26a1{combo}x</span>\n          )}\n        </div>\n\n        <TimerRing progress={timerProgress} seconds={timeLeft} totalSec={timeSec}/>\n\n        <div style={{padding:\"7px 14px\",borderRadius:14,background:th.card,border:`1.5px solid ${th.cardBorder}`,fontSize:12,fontWeight:800,color:th.text,boxShadow:th.cardShadow}}>{round+1}<span style={{color:th.muted}}>/{TOTAL}</span></div>\n      </div>\n\n      {/* Problem \u2014 FIXED HEIGHT */}\n      <div style={{width:\"100%\",maxWidth:480,height:100,background:th.card,borderRadius:24,border:`1.5px solid ${th.cardBorder}`,boxShadow:th.cardShadow,display:\"flex\",flexDirection:\"column\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,position:\"relative\",overflow:\"hidden\"}}>\n        <div style={{position:\"absolute\",top:-20,right:-20,fontSize:60,opacity:0.04,pointerEvents:\"none\"}}>\ud83d\udd22</div>\n        <div style={{fontSize:10,letterSpacing:3,color:th.muted,textTransform:\"uppercase\",fontWeight:800,marginBottom:4}}>Berapa Hasilnya?</div>\n        {problem&&(\n          <div key={`${problem.a}${problem.op}${problem.b}`} className=\"chisa-pop\" style={{fontSize:problem.a>=10||problem.b>=10?40:52,fontWeight:900,lineHeight:1.1,color:th.accent,fontFamily:\"Fredoka One,cursive\",letterSpacing:-1}}>\n            {problem.a} {problem.op} {problem.b} = ?\n          </div>\n        )}\n      </div>\n\n      {/* Feedback \u2014 FIXED HEIGHT */}\n      <div style={{width:\"100%\",maxWidth:480,height:38,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0}}>\n        {roundResult?(\n          <div key={roundResult} className=\"chisa-pop\" style={{padding:\"6px 20px\",borderRadius:14,fontSize:13,fontWeight:900,color:\"#fff\",fontFamily:\"Fredoka One,cursive\",background:roundResult===\"correct\"?\"linear-gradient(135deg,#00c853,#69f0ae)\":\"linear-gradient(135deg,#ff1744,#ff5252)\",boxShadow:roundResult===\"correct\"?\"0 4px 16px rgba(0,200,83,0.45)\":\"0 4px 16px rgba(255,23,68,0.45)\"}}>\n            {roundResult===\"correct\"&&`\u2705 Benar! ${combo>=3?\"\ud83d\udd25 COMBO \u00d7\"+combo+\"!\":\"\"}`}\n            {roundResult===\"wrong\"&&`\u274c Kamu: ${currentValue} \u00b7 Benar: ${problem?.ans}`}\n            {roundResult===\"timeout\"&&`\u23f0 Waktu Habis! Jawaban: ${problem?.ans}`}\n          </div>\n        ):(\n          <div style={{fontSize:12,color:th.subtext,fontWeight:800}}>\n            Nilai jarimu: <strong style={{color:currentValue===problem?.ans?th.green:th.accent,fontSize:22,fontFamily:\"Fredoka One,cursive\"}}>{currentValue}</strong>\n          </div>\n        )}\n      </div>\n\n      {/* Hands */}\n      <div style={{display:\"flex\",justifyContent:\"center\",gap:14,flexWrap:\"wrap\",flexShrink:0}}>\n        <Hand fingers={FL} active={active} showResult={showResult} roundResult={roundResult} onClick={toggleFinger} side=\"left\" th={th}/>\n        <Hand fingers={FR} active={active} showResult={showResult} roundResult={roundResult} onClick={toggleFinger} side=\"right\" th={th}/>\n      </div>\n\n      {/* Action \u2014 FIXED HEIGHT */}\n      <div style={{width:\"100%\",maxWidth:480,flexShrink:0}}>\n        {!showResult?(\n          <button onClick={handleCheck} style={{width:\"100%\",padding:\"15px\",borderRadius:20,border:\"none\",background:th.accentGrad,color:\"#fff\",fontSize:20,fontWeight:900,cursor:\"pointer\",fontFamily:\"Fredoka One,cursive\",boxShadow:`0 8px 24px ${th.accent}55`,letterSpacing:0.5}}>\n            \u2705 CEK JAWABAN!\n          </button>\n        ):(roundResult===\"wrong\"||roundResult===\"timeout\")?(\n          <div style={{padding:\"10px 16px\",borderRadius:16,background:th.pill,border:`2px solid ${th.pillBorder}`,fontSize:11,color:th.pillText,textAlign:\"center\",fontWeight:800}}>\n            \ud83d\udca1 Jari yang benar: <span style={{color:th.accent}}>\n              {[...getAF(problem?.ans||0)].map(id=>{const f=ALL.find(x=>x.id===id);return `${id.startsWith(\"l\")?\"Kiri\":\"Kanan\"} ${f?.label}`;}).join(\" \u00b7 \")}\n            </span>\n          </div>\n        ):null}\n      </div>\n\n      {/* Bottom info */}\n      <div style={{display:\"flex\",justifyContent:\"space-between\",width:\"100%\",maxWidth:480,alignItems:\"center\"}}>\n        <div style={{display:\"flex\",gap:10,fontSize:10,color:th.muted,fontWeight:700}}>\n          <span>\ud83d\udfe0 tekan</span>\n          <span style={{color:th.green}}>\ud83d\udfe2 benar</span>\n          <span style={{color:th.red}}>\ud83d\udd34 salah</span>\n          <span style={{color:th.muted}}>\u23f1 {timeSec}det</span>\n        </div>\n        <button onClick={handleStop} style={{padding:\"5px 12px\",borderRadius:10,border:`1.5px solid ${th.cardBorder}`,background:th.card,color:th.muted,fontSize:11,fontWeight:700,cursor:\"pointer\",fontFamily:\"Nunito,sans-serif\"}}>\u23f9 Stop</button>\n      </div>\n    </div>\n  );\n}\n\nconst root=ReactDOM.createRoot(document.getElementById('root'));\nroot.render(React.createElement(App));\n</script>\n</body>\n</html>";

export default function App() {
  return (
    <View style={styles.container}>
      <StatusBar style="light" backgroundColor="#ff6d00" />
      <WebView
        source={{ html: GAME_HTML }}
        style={styles.webview}
        javaScriptEnabled={true}
        domStorageEnabled={true}
        allowsInlineMediaPlayback={true}
        mediaPlaybackRequiresUserAction={false}
        startInLoadingState={false}
        scalesPageToFit={false}
        bounces={false}
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        overScrollMode="never"
        mixedContentMode="always"
        originWhitelist={['*']}
        onError={(e) => console.log('WebView error:', e)}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#ff6d00',
  },
  webview: {
    flex: 1,
    backgroundColor: 'transparent',
  },
});
